$$\begin{array}{rcl}
  {\mathbf{v}(t)} & = & {{\mathbf{r}^{\prime}(t) = \langle 2t},e^{ t},(1 + t)e^{ t}\rangle} \\
  {\mathbf{a}(t)} & = & {{\mathbf{v}^{\prime}(t) = \langle 2},e^{ t},(2 + t)e^{ t}\rangle} \\
  \left| \mathbf{v}(t) \right| & = & \sqrt{4t^{2} + e^{2t} + {(1 + t)}^{2}e^{2t}}
  \end{array}$$

$$\begin{array}{rcl}
  {\mathbf{v}(t)} & = & {\mathbf{r}^{\prime}(t) = - a\omega\sin\omega t\mathbf{i} + a\omega\cos\omega t\mathbf{j}} \\
  {\mathbf{a}(t)} & = & {\mathbf{v}^{\prime}(t) = - a\omega^{2}\cos\omega t\mathbf{i} - a\omega^{2}\sin\omega t\mathbf{j}}
  \end{array}$$
